insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51566fba-0f2e-472b-9786-baa55e298382', 'fr', 'Qu’est-ce qui rend un toucher naturel plutôt qu’intrusif ?', '["Il est fréquent", "Il arrive dans des moments chaleureux", "Il est bref et léger", "Il correspond à son niveau de confort"]'::jsonb, 'La fréquence et l’insistance submergent. Le bon moment et l’ajustement créent de l’aisance.')
