insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51c9bf97-c01a-4148-8ca9-32bec583870d', 'fr', 'Elle dit : « Je choisis toujours la mauvaise file. » Que pourrais-tu dire ensuite ?', '["« Oui, ça arrive à tout le monde. »", "« Pourquoi tu penses ça ? »", "« Celle-ci est lente aussi. »", "« Clairement, tu es maudite. Reste avec moi, je porte chance. »"]'::jsonb, 'Une exagération chaleureuse ajoute du culot et lance un rythme ludique.')
