insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('634ce3b6-9096-4656-87e7-87d80d609efd', 'fr', 'Elle crée un moment en te regardant profondément dans les yeux. Que montre le fait de soutenir ce regard ?', '["Un intérêt voulu et l’envie de faire évoluer la dynamique", "Tu es juste poli", "De la nervosité et de la gêne"]'::jsonb, 'Un regard stable exprime en silence une intention romantique.')
