insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('63ef4906-b21c-4006-a7c2-c6651684dc24', 'fr', 'Qu’est-ce qui fait qu’un compliment touche ou tombe à plat ?', '["Précis, sincère, fondé sur une observation de quelque chose qu’elle a choisi", "Centré sur des qualités uniques qui la distinguent", "Sincère et du fond du cœur, sans arrière-pensée", "Toutes les réponses ci-dessus"]'::jsonb, 'Un compliment touche quand il est précis, sincère et lié à des choix qu’elle a faits.')
