insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('645db147-5379-46df-8e63-f2d46db760eb', 'fr', 'Elle rit chaleureusement et se penche vers toi pendant la conversation. Que pourrais-tu faire ensuite ?', '["Garder les mains dans les poches pour rester prudent", "Toucher brièvement et légèrement son avant-bras en souriant", "La prendre tout de suite dans tes bras pour aller plus loin", "Poser la main au creux de son dos pour la guider"]'::jsonb, 'Un toucher bref et léger, quand elle est très impliquée, renforce naturellement l’alchimie.')
