insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('69e57da2-5fe8-46fa-b9e1-c7e7f7579196', 'fr', 'Quel est le but principal d’ajuster la distance quand tu flirtes ?', '["Montrer ta domination", "Faire monter l’attirance le plus vite possible", "Tester ses limites", "Faire correspondre la distance physique au confort émotionnel"]'::jsonb, 'La proximité marche quand elle reflète le confort émotionnel, pas quand elle force ou teste les limites.')
