insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6a0ee7f4-bdfd-47a6-901c-adfd7c6f56fa', 'fr', 'Elle fait des blagues avec aisance pendant la conversation. Quel compliment convient ?', '["« Tu es hilarante, tu devrais faire du stand-up. »", "« Tu es drôle, pour une fille. »", "« J’aime bien ton sens de l’humour, il est vraiment unique. »"]'::jsonb, 'La meilleure réponse reflète l’aisance du moment au lieu d’en rajouter.')
