insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('731d74c4-4ac6-43b0-bdcf-69cb8db3d00d', 'fr', 'Elle dit : « Je viens sûrement trop souvent ici. » Que pourrais-tu dire ensuite ?', '["« À ce stade, ils devraient donner ton nom à une boisson. »", "« C’est un super endroit. »", "« Ce n’est pas possible. »", "« Tu viens tous les combien ? »"]'::jsonb, 'Une exagération ludique et chaleureuse rend le moment mémorable.')
