insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('76d8660f-5734-4d14-9168-b2bd84bfeedf', 'fr', 'Quel est le meilleur moment pour faire un compliment ?', '["Comme toute première phrase", "Juste avant de lui demander son numéro", "Naturellement, après qu’elle a exprimé quelque chose", "Seulement si elle te complimente d’abord"]'::jsonb, 'Un compliment touche le plus quand il naît naturellement de l’échange.')
