insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('78f2a3a1-b8f1-4d88-9854-152a0b2895ec', 'fr', 'Elle dit qu’elle est très compétitive aux jeux de société. Quelle est une réponse drôle ?', '["« La compétition, ça peut être malsain. »", "« Je prends la victoire très au sérieux. »", "« Juste, ne renverse pas la table quand je te bats »", "« Les jeux de société, c’est sympa. »"]'::jsonb, 'Une légère exagération garde l’échange ludique et le fait monter d’un cran.')
