insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('79b0dd38-20dd-41fe-91af-1e353ef1dd35', 'fr', 'Elle finit une histoire et te regarde, dans l’attente. Qu’est-ce qui pourrait créer de la tension sexuelle ?', '["Dire vite « C’est une super histoire » et poser une autre question", "La complimenter tout de suite sur son intelligence", "Détourner le regard et changer de sujet", "Soutenir son regard plus longtemps, sourire lentement et dire doucement : « Tu l’as vraiment bien racontée. »"]'::jsonb, 'Un regard prolongé et une façon de dire chaleureuse ouvrent une possibilité sans pression.')
