insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7a679b53-6378-4e35-9329-c81feb6dbfcb', 'fr', 'Elle recule quand tu touches légèrement son bras. Que dois-tu faire ?', '["Arrêter de la toucher et lui laisser de l’espace immédiatement", "Lui demander si ça lui va", "Te dire qu’elle joue les difficiles"]'::jsonb, 'Arrête immédiatement pour respecter ses limites physiques.')
