insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('897a30cf-cd54-4901-b729-6b351f07085b', 'fr', 'Elle dit : « Je suis nulle pour prendre des décisions. » Comment utiliser le culot ?', '["« Ce n’est pas grave, personne n’est parfait. »", "« Qu’est-ce qui t’aide à décider, d’habitude ? »", "« Prends n’importe quoi, ça ira. »", "« Alors, le menu te fait peur ? »"]'::jsonb, 'Une légère exagération culottée invite à rire et à répondre pour jouer.')
