insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('8fbef46b-8fef-4c0e-a566-41439198e3e7', 'fr', 'Elle se penche légèrement vers toi en riant. Que pourrais-tu faire ?', '["Rester figé à ta distance de départ", "Réduire progressivement l’écart pour t’accorder à son énergie", "Reculer pour lui laisser de l’espace", "Te rapprocher tout de suite très près"]'::jsonb, 'Réponds à son signal de confort pour approfondir naturellement le moment.')
