insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('91ff2d3a-7637-491a-b8c0-a33a6b25a5bd', 'fr', 'Qu’est-ce que le « toucher » quand on flirte ?', '["Un contact physique pour montrer ton assurance et ton intention", "Un contact léger, voulu et ajusté pour créer de l’aisance et de l’attirance", "Passer du verbal au physique pour montrer ton intérêt"]'::jsonb, 'Le toucher marche quand il paraît naturel et ajusté, et qu’il crée de l’aisance plutôt que de la pression.')
