insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('95247c9b-621b-4050-bfa2-a28902ab1b90', 'fr', 'Pourquoi les petits défis créent-ils de l’alchimie plus vite qu’une discussion ordinaire ?', '["Ils créent une petite tension et de l’investissement", "Ils font de deux inconnus des rivaux ou des coéquipiers le temps d’un instant", "Ils demandent sa participation active", "Toutes les réponses ci-dessus"]'::jsonb, 'Un enjeu ludique crée de l’énergie et de l’implication sans vraie pression.')
