insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a25d7cd3-3b21-4ccb-89ba-1cffbbe6a49d', 'fr', 'Pourquoi la répartie aide-t-elle à créer une alchimie romantique ?', '["Elle crée une tension légère et du jeu", "Elle réduit la distance émotionnelle grâce au rire", "Elle garde la conversation sérieuse et polie", "Elle crée une énergie d’aller-retour réciproque"]'::jsonb, 'Le jeu fait la différence entre le flirt et une simple complicité amicale.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('a2f4b225-b8a7-4317-8f9e-d5d7ce3e0c73', 'fr', 'Quels comportements montrent une attention respectueuse ?', '["Continuer la conversation pour la faire changer d’avis", "Accepter « J’ai un copain » sans insister", "Prendre du recul quand elle donne des réponses courtes", "Mettre fin poliment à l’échange quand elle est peu impliquée"]'::jsonb, 'Le respect se voit à la vitesse à laquelle tu t’ajustes et à la propreté de ta sortie quand l’intérêt n’est pas là.')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
